def blocks(g, col=8):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==col and (i,j) not in seen:
                # maximal rectangle
                ww=0
                while j+ww<w and g[i][j+ww]==col: ww+=1
                hh=1
                while i+hh<h and all(g[i+hh][j+x]==col for x in range(ww)): hh+=1
                for a in range(i,i+hh):
                    for b in range(j,j+ww): seen.add((a,b))
                out.append((i,j,hh,ww))
    return out
