            col=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); comp=[]
            while q:
                a,b=q.popleft(); comp.append((a,b))
                for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<h and 0<=y<w and (x,y) not in seen and g[x][y]==col:
